import { gameBoard } from "./gameBoardController";

export function attackHandler() {
    const array = [];
    for (let i = 0; i < 10; i++) {
        array.push(i);
    }

    const value = Math.floor(Math.random() * array.length);
    return value;
}

export function attackAdjacent(value){
    let val = 11;
    while (Math.abs(val - value) > 1){
        val = Math.floor(Math.random() * (value + 1));
    }
    return val; 
}

export function randomPLacing(ships, boardPlayer) {
    const game = gameBoard();
    ships.forEach((ship) => {
        let row;
        let column;
        const value = Math.floor(Math.random() * 2);
        while (ship.coordinate.length == 0) {
            row = attackHandler();
            column = attackHandler();
            game.buildCoordinate(value, row, column, ship, boardPlayer);
        }
    });
}

export function generateCoord(stack){
    let row;
    let column;
    if (stack.length !== 0){
        const random = Math.floor(Math.random() * 2);
        if (random === 1){
            row = stack[0];
            column = attackAdjacent(stack[random]);
        } else{
            column = stack[1];
            row = attackAdjacent(stack[random]);
        }

    } else{
        row = attackHandler();
        column = attackHandler();
    }
    while (stack.length !== 0){
        stack.pop();
    }
    return {
        row,
        column
    }
}