import { boardView } from "./screenController";
import { playerControl } from "./playerControl";
import { gameBoard } from "./gameBoardController";
import {randomPLacing, generateCoord } from "./computerHandler";

export function loadPage() {
    const container = document.querySelector(".container");
    const playerTurn = document.querySelector(".player-turn");
    const player1Div = document.querySelector(".player1-board");
    const player2Div = document.querySelector(".player2-board");
    const player1Ship = document.querySelector(".player1-ship");
    const player2Ship = document.querySelector(".player2-ship");
    const startGameBtn = document.querySelector(".start-game");
    const finishBtn = document.querySelector(".finish");
    const computerBtn = document.querySelector(".computer");
    const playerBtn = document.querySelector(".player");
    const starting = document.querySelector(".starting");
    const shipDiv1 = document.querySelector(".ship-div");
    const shipDiv2 = document.querySelector(".ship-div2");
    const rotateBtn = document.querySelector(".rotate")

    const game = boardView();
    const board = game.board;
    const players = playerControl();
    const shipAll = players.getShip();
    const control = gameBoard();

    game.renderBoard(board.board1, player1Div);
    game.renderBoard(board.board2, player2Div);
    game.renderShip(shipAll.ship1, player1Ship);
    game.renderShip(shipAll.ship2, player2Ship);

    let rotateVal = 0;
    let startGame = false;

    const returnRowAndCol = (e) => {
        const row = parseInt(e.target.dataset.row);
        const column = parseInt(e.target.dataset.column);
        if (row === null || column === null || !e.target.matches(".cell")) return;
        return {
            row,
            column
        }
    }

    function selectShipCoordinate(playerDiv, ship, ships, boardPlayer) { 
        const controller = new AbortController();
        const { signal } = controller;  
        let array = [];

        const addClassToCell = (coordinate, className) => {
            for (const [r, c] of coordinate){
                if (boardPlayer[r][c].ship === null){
                    const elem = playerDiv.querySelector(`.cell[data-row="${r}"][data-column="${c}"]`);
                    if (elem) elem.style.backgroundColor = className;
                }
            }
        }

        const handler = (e) => {
            const rowAndCol = returnRowAndCol(e);
            if (rowAndCol !== undefined){
                let oldCoord = ship.coordinate;
                control.removeOldCoord(oldCoord, boardPlayer)
                control.buildCoordinate(rotateVal, rowAndCol.row, rowAndCol.column, ship, boardPlayer, oldCoord);
                game.renderBoard(boardPlayer, playerDiv);
                if(control.pickedSpot(shipAll.ship1).length === 17){
                    finishBtn.disabled = false;
                    startGameBtn.disabled = false;
                }
            }
            controller.abort();
        }
        
        const handleHover = (e) =>{
            const rowAndCol = returnRowAndCol(e);
            if (rowAndCol !== undefined) {
                const coord = control.buildMouseOver(rotateVal, rowAndCol.row, rowAndCol.column, ship, boardPlayer);
                if (coord !== undefined){
                    addClassToCell(coord, 'rgb(32, 185, 32)');
                    array = [...coord]
                }
            }
        }

        const mouseLeave = () => {
            addClassToCell(array, 'lightblue');
            array.length = 0;
        }

        playerDiv.addEventListener('mouseover', handleHover, { signal })
        playerDiv.addEventListener('click', handler, { signal });
        playerDiv.addEventListener('mouseout', mouseLeave, {signal})
    }

    function selectShip(playerShip) {
        return new Promise((resolve) => {
            const handler = (e) => {
                const index = e.target.dataset.number;
                if (!index || !e.target.matches(".fleet")) return;
                resolve(Number(index));
                playerShip.removeEventListener('click', handler);
            };
            playerShip.addEventListener("click", handler);
        });
    }

    async function run(playerShip, playerDiv, ships, boardPlayer) {
        while (true) {
            const idx = await selectShip(playerShip);
            if (startGame) break;
            selectShipCoordinate(playerDiv, ships[idx], ships, boardPlayer);
        }
    }

    async function attack(callback, div) {
        while (true) {
            await attackShip(
                player2Div,
                shipAll.ship2,
                board.board2,
                players.players[0],
                shipDiv2
            );
            await callback(
                player1Div,
                shipAll.ship1,
                board.board1,
                players.players[1],
                div
            );
        }
    }

    const stack = [];
    function computerAttack(playerDiv, ships, boardPlayer, player, shipdiv) {
        return new Promise((resolve) => {
            const autoComputer = setInterval(async() => {
                const rowAndCol = generateCoord(stack);
                if (rowAndCol !== undefined){
                    const state = control.receiveAttack(boardPlayer, rowAndCol.row, rowAndCol.column);
                    if (!state){
                        return
                    }
                    game.renderRemainingShips(ships, shipdiv);
                    game.renderBoard(boardPlayer, playerDiv);
                    if (control.sunkedShip(ships, player)){
                        game.renderWinner(playerTurn, player)
                        return;
                    }
                    if (state.hit){
                        stack.push(rowAndCol.row)
                        stack.push(rowAndCol.column)
                        return;
                    }
                    game.renderPlayer(players, playerTurn);
                    clearInterval(autoComputer);
                }
            }, 300);
            resolve();
        });
    }

    function attackShip(playerDiv, ships, boardPlayer, player, shipdiv) {
        return new Promise((resolve) => {
            const handler = async (e) => {
                e.preventDefault();
                const rowAndCol = returnRowAndCol(e);
                if (rowAndCol !== undefined){
                    const state = control.receiveAttack(boardPlayer, rowAndCol.row, rowAndCol.column);
                    game.renderRemainingShips(ships, shipdiv);
                    game.renderBoard(boardPlayer, playerDiv, true);
                    if (control.sunkedShip(ships, player)){
                        playerDiv.removeEventListener("click", handler);
                        game.renderWinner(playerTurn, player)
                        return;
                    }
                    if (state.hit || !state) {
                        return;
                    }
                    game.renderPlayer(players, playerTurn);
                    playerDiv.removeEventListener("click", handler);
                    resolve();
                }
            };
            playerDiv.addEventListener("click", handler);
        });
    }

    computerBtn.addEventListener('click', () =>{
        container.style.display = 'flex';
        starting.style.display = 'none';
        finishBtn.remove();
    })

    playerBtn.addEventListener('click', () =>{
        container.style.display = 'flex';
        starting.style.display = 'none';
        startGameBtn.remove();
    })

    startGameBtn.addEventListener("click", () => {
        if (control.pickedSpot(shipAll.ship1).length === 17){
            startGame = true;
            players.players[1].name = 'Computer';
            game.renderBoard(board.board2, player2Div, true);
            game.renderPlayer(players, playerTurn);
            game.renderRemainingShips(shipAll.ship1, shipDiv1);
            game.renderRemainingShips(shipAll.ship2, shipDiv2);
            randomPLacing(shipAll.ship2, board.board2);
            attack(computerAttack, shipDiv1);
             startGameBtn.remove();
             rotateBtn.remove();
        }
    });

    document.addEventListener('keydown', (e) => {
        if (e.key == 'r'){
            if (rotateVal === 0) rotateVal = 1;
            else if (rotateVal === 1) rotateVal = 0;
        }
    })

    run(player1Ship, player1Div, shipAll.ship1, board.board1);
    finishBtn.addEventListener('click', (e) =>{
        if(control.pickedSpot(shipAll.ship1).length === 17){
            e.preventDefault();
            game.renderBoard(board.board1, player1Div, true);
            run(player2Ship, player2Div, shipAll.ship2, board.board2);
            finishBtn.disabled = true;
        }if (control.pickedSpot(shipAll.ship2).length === 17){
            finishBtn.disabled = false;
            startGame = true;
            game.renderPlayer(players, playerTurn);
            game.renderBoard(board.board2, player2Div, true);
            game.renderRemainingShips(shipAll.ship1, shipDiv1);
            game.renderRemainingShips(shipAll.ship2, shipDiv2);
            attack(attackShip, shipDiv1);
            finishBtn.remove();
            rotateBtn.remove();
        }
    })
}
