import { Ship, Player } from "./shipAndPLayerClass";

export function gameBoard() {
    const board1 = [];
    const board2 = [];
    const row = 10;

    for (let i = 0; i < row; i++) {
        board1[i] = [];
        board2[i] = [];
        for (let j = 0; j < row; j++) {
            board1[i][j] = Cell();
            board2[i][j] = Cell();
        }
    }

    const addShip = (ship) => {
        const ship5length = new Ship(5, "Aircraft Carriers", 0);
        const ship4length = new Ship(4, "Destroyer", 0);
        const ship3length = new Ship(3, "Coast Guard", 0);
        const ship3length2 = new Ship(3, "Border Patrol", 0);
        const ship2length = new Ship(2, "Fishing Boat", 0);
        ship.push(
            ship5length,
            ship4length,
            ship3length,
            ship3length2,
            ship2length,
        );
    };
    
    const shipPlaceValid = (row, col, ship, boardPlayer, val) => {
        const length = ship.length
        if (val === 1){
            if (row + length > 10) return false;
            for (let i = row; i < row + length; i++){
                if (boardPlayer[i][col].ship) return false;
            }
        }  
        else {
            if (col + length > 10) return false;
            for (let i = col; i < col + length; i++){
                if (boardPlayer[row][i].ship) return false;
            }
        }
        return true;
    }

    const getBoard = () => {
        return {
            board1,
            board2,
        };
    };

    const removeOldCoord = (coordinate, boardPlayer, ) =>{
        for (const [r, c] of coordinate){
            boardPlayer[r][c].ship = null;
        }
        coordinate.length = 0;
    }

    const buildCoordinate = (val, row, col, ship, boardPlayer) => {
        const coordinate = [];

        if (!shipPlaceValid(row, col, ship, boardPlayer, val)) 
            return
        if(val === 0){
            for (let i = 0; i < ship.length; i++) {
                coordinate[i] = []
                coordinate[i].push(row, col + i);
            }
            for (let c = col; c < col + ship.length; c++){
                boardPlayer[row][c].ship = ship 
            }
        }
        else {
            for (let i = 0; i < ship.length; i++) {
                coordinate[i] = []
                coordinate[i].push(row + i, col);
            }
            for (let r = row; r < row + ship.length; r++){
                boardPlayer[r][col].ship = ship
            }
        }
        ship.setCoordinate(coordinate);
    };

    const buildMouseOver = (val, row, col, ship ,boardPlayer) => {
       const coordinate = [];

       if (!shipPlaceValid(row, col, ship, boardPlayer, val)) 
            return
        if(val === 0){
            for (let i = 0; i < ship.length; i++) {
                coordinate[i] = []
                coordinate[i].push(row, col + i);
            }
        }
        else {
            for (let i = 0; i < ship.length; i++) {
                coordinate[i] = []
                coordinate[i].push(row + i, col);
            }

        }

        return coordinate;
    }

    const pickedSpot = (ships) => {
        const render = ships.flatMap((ship) => ship.coordinate);
        return render;
    };

    function receiveAttack(board, row, col) {
        if (row < 0 || col < 0 || row >= 10 || col >= 10) return;
        const cell = board[row][col];
        if (cell.firedUpon) return false;
        cell.firedUpon = true;

        let hit = false
        let sunk = false;
        if (cell.ship) {
            cell.ship.hit();
            hit = true;
            if (cell.ship.isSunk()) sunk = true;
        }
        return { hit, sunk };
    }   

    const sunkedShip = (ships, player) => {
        for (let i = 0; i < ships.length; i++) {
            if (ships[i].isSunk() === true) {
                console.log(`${ships[i].name} has been destroyed`)
                ships.splice(i, 1);
            }
        }
        if (ships.length === 0) {
            console.log(`${player.name} win`);
            return true;
        }
    };

    return {
        row,
        getBoard,
        addShip,
        buildCoordinate,
        pickedSpot,
        receiveAttack,
        sunkedShip,
        buildMouseOver,
        removeOldCoord
    };
}

// change color for cell that are chiem dung boi ship
function Cell() {
    return {
        firedUpon: false,
        ship: null,
    };
}
