import { Player, Ship } from "./shipAndPLayerClass";
import { gameBoard } from "./gameBoardController";

export function playerControl() {
    let ship1 = [];
    let ship2 = [];
    const game = gameBoard();
    const players = [new Player("Player 1"), new Player("Player 2")];

    const getShip = () => {
        return {
            ship1,
            ship2,
        };
    };

    let activePlayer = players[1];
    const playerTurn = () => {
        activePlayer = activePlayer === players[0] ? players[1] : players[0];
    };

    const getActivePlayer = () => {
        playerTurn();
        return activePlayer;
    };

    game.addShip(ship1);
    game.addShip(ship2);

    return {
        players,
        getActivePlayer,
        getShip,
    };
}
