import { gameBoard } from "./gameBoardController";

export function boardView() {
    const game = gameBoard();
    const board = game.getBoard();

    const renderBoard = (playerBoard, playerDiv, hideShip) => {
        playerDiv.innerHTML = "";
        playerBoard.forEach((row, idx) => {
            row.forEach((cell, index) => {
                const btn = document.createElement("button");
                btn.className = "cell"; 
                if (cell.firedUpon){
                    btn.style.backgroundColor = cell.ship ? "rgb(242, 81, 81)" : "rgb(171, 168, 168)";
                }
                else if (hideShip && cell.ship){
                    btn.style.backgroundColor = "lightblue";
                }
                else if(cell.ship){
                    btn.style.backgroundColor = "rgb(32, 185, 32)";
                }
                else {
                    btn.style.backgroundColor = "lightblue";
                }
                btn.dataset.row = idx;
                btn.dataset.column = index;
                playerDiv.appendChild(btn);
            });
        });
    };

    const renderShip = (ships, shipDiv) => {
        shipDiv.innerHTML = "";
        ships.forEach((ship, index) => {
            const button1 = document.createElement("button");
            button1.textContent = ship.name;
            button1.dataset.number = index;
            button1.className = "fleet";
            shipDiv.appendChild(button1);
        });
    };

    const renderPlayer = (players, container) => {
        container.innerHTML = "";
        const playerTurn = document.createElement("div");
        playerTurn.textContent = `${players.getActivePlayer().name}'s turn`;
        container.appendChild(playerTurn);
    };

    const renderBoardColor = (boardPlayer) => {
        for (let i = 0; i < game.row; i++){
            for (let j = 0; j < 10; j++){
                boardPlayer[i][j].addValue("lightblue");
            }
        }
    }
    
    const renderRemainingShips = (ships, shipsDiv) => {
        shipsDiv.innerHTML = '<p class="remain">Remaining Ships:</p>';
        ships.forEach((ship) =>{
            const shipName = document.createElement("p");
            shipName.textContent = ship.name + `(Length: ${ship.length})`;
            shipName.className = 'ship-name';
            shipsDiv.appendChild(shipName);
        })
    }

    const renderWinner = (parentNode, player) =>{
        parentNode.innerHTML = '';
        parentNode.textContent = `${player.name} win (Please refresh to play again)`
        parentNode.style.fontSize = '2rem'
    }

    return {
        renderBoard,
        renderShip,
        board,
        renderPlayer,
        renderBoardColor,
        renderRemainingShips,
        renderWinner
    };
}
