export class Ship {
    constructor(length, name, hits) {
        this.length = length;
        this.hits = hits;
        this.sunk = false;
        this.name = name;
        this.coordinate = [];
    }
    hit() {
        this.hits++;
    }

    getHit() {
        return this.hits;
    }

    setCoordinate(shipCoordinate) {
        this.coordinate = shipCoordinate;
    }


    getCoordinate() {
        return this.coordinate;
    }

    isSunk() {
        if (this.getHit() === this.length) {
            this.sunk = true;
        }
        return this.sunk;
    }
}

export class Player {
    constructor(name) {
        this.name = name;
        this.score = 0;
    }

    updateScore() {
        this.score++;
    }
}
